def batch_acceptance_register(history):
    rows=[]
    for step in range(329,338):
        if step==337:
            confirmation=PREDECESSOR_CONFIRMATION;receipt=PREDECESSOR_RECEIPT
            source='current338 external complete337 receipt/confirmation, separately bound by own artifact SHA'
        else:
            base=WORKSTREAM_BASES[str(step+1)]
            confirmation=json.loads(history[FIXTURE+'/'+base+'-checkpoint-confirmation.json'])
            receipt=json.loads(history[FIXTURE+'/'+base+f'-step{step}-user-acceptance.json'])
            source=FIXTURE+'/'+base+f'-step{step}-user-acceptance.json'
        prefix,count,message=EXPECTED_BATCH_ACCEPTANCES[str(step)]
        exact(confirmation['step'],step,'batch accepted predecessor step');exact(confirmation['commit_prefix'],prefix,'batch accepted prefix')
        exact(confirmation['acceptance_result'],f'PASS ({count} passes, 0 failures)','batch exact acceptance')
        for key in ['user_application_completed','user_harness_completed','user_commit_and_push_completed','user_head_matches_origin','user_worktree_clean','complete_ordered_return_matches_prepared_and_installed']:exact(confirmation[key],True,'complete batch return '+key)
        raw=receipt['text'].encode();exact(sha(raw),receipt['original_display_sha256'],'complete receipt bytes');exact(len(raw),receipt['original_display_size_bytes'],'complete receipt size')
        lines=receipt['text'].splitlines()
        exact(sum(line.startswith('PASS: ') for line in lines),count,'complete batch ordered output count')
        exact(lines.count(f'Result: PASS ({count} passes, 0 failures)'),1,'one complete batch acceptance summary')
        exact(lines.count(prefix+' (HEAD -> main, origin/main, origin/HEAD) '+message),2,'matching batch HEAD-origin logs')
        if '..'+prefix+'  main -> main' not in receipt['text']:raise ValueError('batch successful push missing')
        rows.append(dict(step=step,commit_prefix=prefix,commit_full=None,acceptance=confirmation['acceptance_result'],
                         complete_user_acceptance=True,source=source,complete_receipt_sha256=sha(raw),
                         scope='reported-complete-user-return-not-independent-host-or-GitHub-inspection'))
    return rows

